/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-09: new module - observer of the flow file and the credentials file of the
 *   file storage (watchFlows), for instances that share the files on a volume
 *   Z-09: the last known content is kept per observer (noteWrite updates all)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Observes the flow file and the credentials file of the file storage (Z-09,
 * `watchFlows`). Two sources of events, both debounced into one check of the
 * content:
 *
 * - `fs.watch` of the directories of the files - fast, local changes;
 * - `fs.watchFile` (stat polling) - also changes made by another host on a
 *   shared volume, where file system events are not delivered.
 *
 * A file is reported only when its content differs from the last known one:
 * the content written by this process (`noteWrite`, called by the storage
 * before it writes) and a rewrite with the same content are not reported. An
 * empty, missing or not parseable file is skipped (a write in progress) until
 * its content is valid.
 * @module
 */

const fs = require("fs");
const fspath = require("path");
const crypto = require("crypto");

const DEBOUNCE = 200;
const POLL_INTERVAL = 1000;

// The active observers: each has its own map path -> hash of the last known
// content (written by this process or reported to that observer), so two
// observers of the same file in one process are notified independently
const observers = new Set();

function hash(content) {
    return crypto.createHash("sha256").update(content).digest("hex");
}

function stripBom(content) {
    return content.charCodeAt(0) === 0xFEFF ? content.slice(1) : content;
}

/**
 * Records the content this process writes to a file, so the observer does not
 * report it as a change by another instance.
 * @param {string} path
 * @param {string} content
 */
function noteWrite(path, content) {
    const h = hash(content);
    observers.forEach(function(known) {
        known.set(path, h);
    });
}

function readContent(path) {
    return new Promise(function(resolve) {
        fs.readFile(path, "utf8", function(err, data) {
            resolve(err ? null : data);
        });
    });
}

/**
 * Starts observing the files.
 * @param {Object} files
 * @param {string} files.flows - the flow file
 * @param {string} [files.credentials] - the credentials file
 * @param {function({rev?: string, credentialsChanged: boolean, source: string})} callback
 * @param {Object} [options]
 * @param {Object} [options.log]
 * @param {number} [options.debounce]
 * @param {number} [options.interval] - the polling interval in ms
 * @return {Promise<function(): Promise<void>>} - stops observing
 */
async function watchFiles(files, callback, options) {
    options = options || {};
    const log = options.log;
    const debounce = options.debounce || DEBOUNCE;
    const interval = options.interval || POLL_INTERVAL;
    const entries = [{ kind: "flows", path: files.flows }];
    if (files.credentials) {
        entries.push({ kind: "credentials", path: files.credentials });
    }
    const known = new Map();
    observers.add(known);
    for (const entry of entries) {
        const content = await readContent(entry.path);
        if (content !== null && content.length > 0) {
            known.set(entry.path, hash(content));
        }
    }

    let stopped = false;
    let timer = null;
    let checking = null;
    let again = false;
    const watchers = [];

    function trigger() {
        if (stopped) {
            return;
        }
        if (timer) {
            clearTimeout(timer);
        }
        timer = setTimeout(function() {
            timer = null;
            check();
        }, debounce);
    }

    function check() {
        if (checking) {
            again = true;
            return;
        }
        checking = (async function() {
            const changed = {};
            let rev;
            for (const entry of entries) {
                const content = await readContent(entry.path);
                if (content === null || content.length === 0) {
                    continue;
                }
                const h = hash(content);
                if (known.get(entry.path) === h) {
                    continue;
                }
                let parsed;
                try {
                    parsed = JSON.parse(stripBom(content));
                } catch (err) {
                    // A write in progress: checked again on the next event
                    continue;
                }
                known.set(entry.path, h);
                changed[entry.kind] = true;
                if (entry.kind === "flows") {
                    rev = hash(JSON.stringify(parsed));
                }
            }
            if (!stopped && (changed.flows || changed.credentials)) {
                const notification = { credentialsChanged: !!changed.credentials, source: "file" };
                if (rev !== undefined) {
                    notification.rev = rev;
                }
                try {
                    callback(notification);
                } catch (err) {
                    if (log) {
                        log.debug("watchFlows callback failed: " + ((err && err.message) || err));
                    }
                }
            }
        })().catch(function(err) {
            if (log) {
                log.debug("watchFlows check failed: " + ((err && err.message) || err));
            }
        }).then(function() {
            checking = null;
            if (again && !stopped) {
                again = false;
                check();
            }
        });
    }

    const dirs = {};
    entries.forEach(function(entry) {
        const dir = fspath.dirname(entry.path);
        dirs[dir] = dirs[dir] || [];
        dirs[dir].push(fspath.basename(entry.path));
    });
    Object.keys(dirs).forEach(function(dir) {
        try {
            const watcher = fs.watch(dir, { persistent: false }, function(event, filename) {
                if (!filename || dirs[dir].indexOf(String(filename)) !== -1) {
                    trigger();
                }
            });
            watcher.on("error", function(err) {
                if (log) {
                    log.debug("watchFlows: fs.watch failed: " + ((err && err.message) || err));
                }
            });
            watchers.push(watcher);
        } catch (err) {
            // No file system events (for example the directory is missing):
            // polling only
            if (log) {
                log.debug("watchFlows: fs.watch not available for " + dir + ": " + ((err && err.message) || err));
            }
        }
    });
    const pollListener = function(curr, prev) {
        if (curr.mtimeMs !== prev.mtimeMs || curr.size !== prev.size || curr.ino !== prev.ino) {
            trigger();
        }
    };
    entries.forEach(function(entry) {
        fs.watchFile(entry.path, { persistent: false, interval: interval }, pollListener);
    });

    return async function unwatch() {
        if (stopped) {
            return;
        }
        stopped = true;
        observers.delete(known);
        if (timer) {
            clearTimeout(timer);
            timer = null;
        }
        watchers.forEach(function(watcher) {
            try {
                watcher.close();
            } catch (err) {}
        });
        entries.forEach(function(entry) {
            fs.unwatchFile(entry.path, pollListener);
        });
        if (checking) {
            await checking;
        }
    };
}

module.exports = {
    watchFiles: watchFiles,
    noteWrite: noteWrite
};
